from __future__ import annotations

DASHBOARD_HTML = r'''<!doctype html>
<html lang="fr">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <meta name="theme-color" content="#050914">
  <title>Louis OS</title>
  <style>
    :root{--bg:#040812;--bg2:#09101f;--panel:rgba(10,18,34,.86);--panel2:rgba(13,24,45,.93);--line:rgba(100,132,190,.19);--text:#f5f8ff;--muted:#8fa4c8;--cyan:#18bff2;--blue:#4279ff;--violet:#8b42ff;--green:#20d7a0;--red:#ff6685;--amber:#ffc857;--shadow:0 26px 70px rgba(0,0,0,.38)}
    *{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;color:var(--text);font:15px/1.5 Inter,ui-sans-serif,system-ui,-apple-system,Segoe UI,sans-serif;min-height:100vh;background:radial-gradient(circle at 74% 7%,rgba(91,49,255,.18),transparent 30%),radial-gradient(circle at 24% -5%,rgba(0,194,255,.14),transparent 28%),linear-gradient(155deg,#03060d 0%,#07101d 52%,#040711 100%);overflow-x:hidden}body:before{content:"";position:fixed;inset:0;pointer-events:none;background-image:linear-gradient(rgba(255,255,255,.012) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.012) 1px,transparent 1px);background-size:46px 46px;mask-image:linear-gradient(to bottom,black,transparent 85%)}button,input,textarea,select{font:inherit}.app{display:grid;grid-template-columns:270px minmax(0,1fr);min-height:100vh}.sidebar{padding:25px 18px;border-right:1px solid var(--line);background:rgba(3,8,18,.82);backdrop-filter:blur(22px);position:sticky;top:0;height:100vh;z-index:4}.brand{display:flex;align-items:center;gap:13px;margin:3px 8px 31px}.logo{width:45px;height:45px;border-radius:15px;background:linear-gradient(145deg,var(--cyan),var(--blue) 52%,var(--violet));display:grid;place-items:center;font-weight:900;font-size:18px;box-shadow:0 0 0 1px rgba(255,255,255,.12),0 12px 35px rgba(65,91,255,.34);position:relative}.logo:after{content:"";width:18px;height:18px;border:4px solid #061020;border-radius:6px;transform:rotate(30deg)}.brand h1{font-size:19px;letter-spacing:.08em;margin:0}.brand small{color:var(--muted);font-size:11px;letter-spacing:.12em;text-transform:uppercase}nav{display:grid;gap:8px}.nav{border:1px solid transparent;background:transparent;color:var(--muted);text-align:left;padding:12px 14px;border-radius:12px;cursor:pointer;transition:.2s}.nav:hover,.nav.active{background:linear-gradient(90deg,rgba(18,191,242,.12),rgba(139,66,255,.08));border-color:rgba(62,139,255,.22);color:#fff;box-shadow:inset 3px 0 0 var(--cyan)}.sidebar-foot{position:absolute;bottom:22px;left:18px;right:18px}.status-pill{display:flex;align-items:center;gap:9px;padding:12px 13px;border:1px solid var(--line);border-radius:14px;color:var(--muted);background:rgba(11,20,39,.76)}.dot{width:8px;height:8px;border-radius:50%;background:var(--amber)}.dot.ok{background:var(--green);box-shadow:0 0 16px rgba(32,215,160,.85)}main{padding:31px;max-width:1580px;width:100%;position:relative}.topbar{display:flex;justify-content:space-between;align-items:flex-start;gap:20px;margin-bottom:24px}.eyebrow{color:var(--cyan);font-size:12px;font-weight:800;letter-spacing:.16em;text-transform:uppercase;margin-bottom:6px}.topbar h2{font-size:31px;letter-spacing:-.03em;margin:0 0 4px}.muted{color:var(--muted)}.actions{display:flex;gap:10px;flex-wrap:wrap}.btn{border:1px solid var(--line);border-radius:12px;padding:10px 15px;background:rgba(13,24,45,.82);color:var(--text);cursor:pointer;transition:.2s}.btn:hover{border-color:rgba(69,137,255,.6);transform:translateY(-1px)}.btn.primary{background:linear-gradient(110deg,var(--cyan),var(--blue) 50%,var(--violet));border:0;box-shadow:0 10px 30px rgba(59,97,255,.25)}.grid{display:grid;gap:18px}.stats{grid-template-columns:repeat(4,minmax(0,1fr));margin-bottom:18px}.card{position:relative;overflow:hidden;background:linear-gradient(155deg,rgba(16,29,53,.91),rgba(7,14,28,.91));border:1px solid var(--line);border-radius:18px;padding:20px;box-shadow:var(--shadow)}.card:before{content:"";position:absolute;inset:0 0 auto 0;height:1px;background:linear-gradient(90deg,transparent,rgba(24,191,242,.65),rgba(139,66,255,.5),transparent)}.stat{min-height:125px}.stat-icon{width:38px;height:38px;border:1px solid rgba(75,135,255,.25);background:rgba(29,54,99,.38);border-radius:12px;display:grid;place-items:center;color:var(--cyan);font-size:18px;margin-bottom:15px}.stat-label{color:var(--muted);font-size:12px;text-transform:uppercase;letter-spacing:.08em}.stat-value{font-size:29px;font-weight:850;margin-top:6px;letter-spacing:-.03em}.stat-note{color:var(--muted);font-size:11px;margin-top:5px}.two{grid-template-columns:minmax(0,1.45fr) minmax(320px,.75fr)}.hero{margin-bottom:18px;display:grid;grid-template-columns:1.2fr .8fr;min-height:230px}.hero-copy{padding:3px 10px 3px 2px}.hero h3{font-size:34px;line-height:1.12;letter-spacing:-.04em;margin:6px 0 14px;max-width:650px}.gradient-text{background:linear-gradient(90deg,var(--cyan),#6d8fff,var(--violet));-webkit-background-clip:text;background-clip:text;color:transparent}.hero p{color:var(--muted);max-width:650px;font-size:16px}.hero-visual{position:relative;min-height:190px}.orb{position:absolute;border-radius:50%;filter:blur(1px)}.orb.one{width:190px;height:190px;right:8%;top:-10px;background:radial-gradient(circle at 35% 35%,rgba(24,191,242,.85),rgba(66,121,255,.35) 42%,rgba(139,66,255,.08) 68%,transparent 70%);box-shadow:0 0 70px rgba(66,121,255,.24)}.orb.two{width:115px;height:115px;right:44%;bottom:-6px;border:1px solid rgba(124,81,255,.55);background:rgba(39,46,112,.17)}.core-ring{position:absolute;right:19%;top:38px;width:112px;height:112px;border:1px solid rgba(255,255,255,.23);border-radius:50%;display:grid;place-items:center;box-shadow:inset 0 0 30px rgba(42,117,255,.22)}.core-ring:before,.core-ring:after{content:"";position:absolute;border-radius:50%;border:1px solid rgba(24,191,242,.28)}.core-ring:before{inset:12px}.core-ring:after{inset:28px}.core-ring b{font-size:18px;z-index:1}.card h3{margin:0 0 16px;font-size:17px}.mission-list{display:grid;gap:10px}.mission{display:grid;grid-template-columns:1fr auto;gap:14px;padding:14px 15px;border:1px solid var(--line);border-radius:13px;background:rgba(4,10,21,.52);cursor:pointer;transition:.18s}.mission:hover{border-color:rgba(63,130,255,.48);background:rgba(12,26,48,.74);transform:translateX(2px)}.mission-title{font-weight:720}.mission-meta{font-size:12px;color:var(--muted);margin-top:4px}.badge{padding:4px 9px;border-radius:99px;font-size:11px;font-weight:750;background:rgba(32,215,160,.12);color:var(--green);height:max-content;border:1px solid rgba(32,215,160,.18)}.badge.failed{background:rgba(255,102,133,.12);color:var(--red);border-color:rgba(255,102,133,.18)}.badge.approval_required{background:rgba(255,200,87,.12);color:var(--amber);border-color:rgba(255,200,87,.2)}label{display:block;color:var(--muted);font-size:12px;margin-bottom:6px}input,textarea,select{width:100%;border:1px solid var(--line);background:rgba(3,9,20,.78);color:var(--text);border-radius:11px;padding:11px 12px;outline:none}textarea{min-height:116px;resize:vertical}input:focus,textarea:focus,select:focus{border-color:var(--cyan);box-shadow:0 0 0 3px rgba(24,191,242,.08)}.field{margin-bottom:13px}.form-row{display:grid;grid-template-columns:1fr 1fr;gap:12px}.output{white-space:pre-wrap;background:#030914;border:1px solid var(--line);border-radius:13px;padding:15px;max-height:510px;overflow:auto;color:#dce8ff;font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:13px}.empty{padding:28px;text-align:center;color:var(--muted);border:1px dashed rgba(107,133,182,.27);border-radius:13px}.keybox{display:flex;gap:8px}.keybox input{flex:1}.toast{position:fixed;right:22px;bottom:22px;background:#101c35;border:1px solid rgba(71,134,255,.3);padding:13px 16px;border-radius:13px;box-shadow:var(--shadow);opacity:0;transform:translateY(12px);pointer-events:none;transition:.2s;z-index:20}.toast.show{opacity:1;transform:none}.section{display:none}.section.active{display:block}.capability{display:grid;grid-template-columns:38px 1fr;gap:12px;align-items:center;padding:12px 0;border-bottom:1px solid var(--line)}.capability:last-child{border-bottom:0}.capability .ci{width:38px;height:38px;border-radius:11px;background:linear-gradient(145deg,rgba(24,191,242,.16),rgba(139,66,255,.12));display:grid;place-items:center;color:var(--cyan)}.trace{position:relative;padding:13px 14px 13px 38px;border-left:1px solid rgba(70,127,255,.25);margin-left:10px}.trace:before{content:"";position:absolute;left:-5px;top:19px;width:9px;height:9px;background:var(--cyan);border-radius:50%;box-shadow:0 0 14px rgba(24,191,242,.7)}.trace-agent{font-weight:750}.trace-stage{font-size:12px;color:var(--cyan);text-transform:uppercase;letter-spacing:.08em}.trace-output{color:var(--muted);font-size:12px;max-height:82px;overflow:hidden;margin-top:5px;white-space:pre-wrap}.agent-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.agent-card{padding:17px;border:1px solid var(--line);border-radius:15px;background:rgba(5,12,25,.6)}.agent-card b{display:block;margin:8px 0 3px}.agent-icon{width:39px;height:39px;border-radius:12px;background:linear-gradient(145deg,rgba(24,191,242,.18),rgba(139,66,255,.16));display:grid;place-items:center;color:var(--cyan)}
    @media(max-width:1050px){.app{grid-template-columns:1fr}.sidebar{position:relative;height:auto;border-right:0;border-bottom:1px solid var(--line)}nav{grid-template-columns:repeat(5,1fr)}.sidebar-foot{display:none}.stats{grid-template-columns:repeat(2,1fr)}.two,.hero{grid-template-columns:1fr}.hero-visual{min-height:150px}.agent-grid{grid-template-columns:repeat(2,1fr)}}
    @media(max-width:640px){main{padding:17px}.topbar{display:block}.actions{margin-top:13px}.stats{grid-template-columns:1fr 1fr;gap:12px}.stat{min-height:112px;padding:16px}.stat-value{font-size:24px}.form-row,.agent-grid{grid-template-columns:1fr}nav{grid-template-columns:1fr 1fr}.sidebar{padding:15px}.brand{margin-bottom:15px}.hero h3{font-size:28px}.hero-visual{display:none}.card{border-radius:15px}.two{gap:14px}}
  </style>
</head>
<body>
<div class="app">
  <aside class="sidebar">
    <div class="brand"><div class="logo"></div><div><h1>LOUIS OS</h1><small>Intelligent Operating System</small></div></div>
    <nav>
      <button class="nav active" data-page="overview">⌂ &nbsp; Vue d'ensemble</button>
      <button class="nav" data-page="missions">◎ &nbsp; Missions</button>
      <button class="nav" data-page="agents">◇ &nbsp; Agents</button>
      <button class="nav" data-page="memory">◉ &nbsp; Mémoire</button>
      <button class="nav" data-page="system">⚙ &nbsp; Système</button>
    </nav>
    <div class="sidebar-foot"><div class="status-pill"><span id="statusDot" class="dot"></span><span id="statusText">Connexion...</span></div></div>
  </aside>
  <main>
    <section id="overview" class="section active">
      <div class="topbar"><div><div class="eyebrow">Overview</div><h2>Centre de contrôle</h2><div class="muted">Tes missions. Notre intelligence. Des résultats concrets.</div></div><div class="actions"><button class="btn" onclick="refreshAll()">Actualiser</button><button class="btn primary" onclick="showPage('missions')">＋ Nouvelle mission</button></div></div>
      <div class="card hero"><div class="hero-copy"><div class="eyebrow">Louis Core</div><h3>Un système qui <span class="gradient-text">pense, agit et se souvient.</span></h3><p>Louis OS orchestre plusieurs agents, exploite sa mémoire persistante et transforme chaque objectif en exécution structurée, contrôlée et traçable.</p><button class="btn primary" onclick="showPage('missions')">Lancer une mission →</button></div><div class="hero-visual"><div class="orb one"></div><div class="orb two"></div><div class="core-ring"><b>LOUIS</b></div></div></div>
      <div class="grid stats">
        <div class="card stat"><div class="stat-icon">●</div><div class="stat-label">État du système</div><div id="systemState" class="stat-value">—</div><div class="stat-note">Cloud runtime</div></div>
        <div class="card stat"><div class="stat-icon">↗</div><div class="stat-label">Missions récentes</div><div id="missionCount" class="stat-value">—</div><div class="stat-note">Derniers enregistrements</div></div>
        <div class="card stat"><div class="stat-icon">✓</div><div class="stat-label">Taux de succès</div><div id="successRate" class="stat-value">—</div><div class="stat-note">Missions terminées</div></div>
        <div class="card stat"><div class="stat-icon">◉</div><div class="stat-label">Stockage</div><div id="storeType" class="stat-value">—</div><div class="stat-note">Mémoire persistante</div></div>
      </div>
      <div class="grid two"><div class="card"><h3>Dernières missions</h3><div id="recentMissions" class="mission-list"><div class="empty">Aucune mission chargée</div></div></div><div class="card"><h3>Capacités actives</h3><div class="capability"><div class="ci">◇</div><div><b>Orchestration multi-agent</b><div class="muted">Planner, spécialiste, critique et synthèse.</div></div></div><div class="capability"><div class="ci">◉</div><div><b>Mémoire persistante</b><div class="muted">Contexte réutilisable et traçable.</div></div></div><div class="capability"><div class="ci">ϟ</div><div><b>Missions automatisées</b><div class="muted">Exécution structurée de bout en bout.</div></div></div><div class="capability"><div class="ci">✓</div><div><b>Session web sécurisée</b><div class="muted">Une clé d’accès explicite est échangée contre un cookie court et sécurisé.</div></div></div><button class="btn" onclick="authenticate()">Se connecter</button><div id="capabilities" class="muted" style="margin-top:14px">Chargement...</div></div></div>
    </section>
    <section id="missions" class="section">
      <div class="topbar"><div><div class="eyebrow">Execution</div><h2>Missions</h2><div class="muted">Créer une mission structurée et inspecter son exécution complète.</div></div><button class="btn" onclick="loadMissions()">Actualiser</button></div>
      <div class="grid two"><div class="card"><h3>Nouvelle mission</h3><form id="missionForm"><div class="form-row"><div class="field"><label>Type</label><select id="missionType"><option value="research">Recherche</option><option value="supplier_qualification">Qualification fournisseur</option><option value="import_cost_analysis">Analyse coût import</option><option value="industrial_analysis">Analyse industrielle</option></select></div><div class="field"><label>Domaine</label><input id="missionDomain" value="industrial"></div></div><div class="field"><label>Objectif</label><textarea id="missionObjective" required placeholder="Décris précisément le résultat attendu..."></textarea></div><div class="field"><label>Contexte JSON</label><textarea id="missionContext">{}</textarea></div><button class="btn primary" type="submit">Lancer la mission</button></form></div><div class="card"><h3>Résultat</h3><div id="missionOutput" class="output">Aucune mission exécutée.</div><div id="traceOutput" style="margin-top:16px"></div></div></div>
      <div class="card" style="margin-top:18px"><h3>Historique</h3><div id="missionHistory" class="mission-list"><div class="empty">Chargement...</div></div></div>
    </section>
    <section id="agents" class="section"><div class="topbar"><div><div class="eyebrow">Multi-agent system</div><h2>Agents</h2><div class="muted">Les rôles spécialisés qui composent le moteur Louis OS.</div></div></div><div class="agent-grid"><div class="agent-card"><div class="agent-icon">P</div><b>Planner</b><span class="muted">Décompose et sécurise la mission.</span></div><div class="agent-card"><div class="agent-icon">R</div><b>Research Agent</b><span class="muted">Analyse faits, hypothèses et informations manquantes.</span></div><div class="agent-card"><div class="agent-icon">E</div><b>Engineering Agent</b><span class="muted">Conçoit des solutions techniques testables.</span></div><div class="agent-card"><div class="agent-icon">C</div><b>Critic Agent</b><span class="muted">Vérifie qualité, sécurité et complétude.</span></div><div class="agent-card"><div class="agent-icon">S</div><b>Synthesizer</b><span class="muted">Produit une réponse finale claire et actionnable.</span></div><div class="agent-card"><div class="agent-icon">M</div><b>Memory Layer</b><span class="muted">Injecte le contexte durable pertinent.</span></div></div></section>
    <section id="memory" class="section"><div class="topbar"><div><div class="eyebrow">Knowledge</div><h2>Mémoire</h2><div class="muted">Connaissances persistantes et réutilisables par Louis OS.</div></div><button class="btn" onclick="loadMemories()">Actualiser</button></div><div class="grid two"><div class="card"><h3>Rechercher</h3><div class="keybox"><input id="memoryQuery" placeholder="Rechercher dans la mémoire..."><button class="btn primary" onclick="loadMemories()">Chercher</button></div><div id="memoryList" class="mission-list" style="margin-top:16px"><div class="empty">Aucune mémoire chargée</div></div></div><div class="card"><h3>Ajouter une mémoire</h3><div class="field"><label>Domaine</label><input id="memoryDomain" value="industrial"></div><div class="field"><label>Type</label><select id="memoryType"><option value="fact">Fait</option><option value="preference">Préférence</option><option value="decision">Décision</option><option value="procedure">Procédure</option><option value="outcome">Résultat</option></select></div><div class="field"><label>Contenu</label><textarea id="memoryContent"></textarea></div><button class="btn primary" onclick="createMemory()">Mémoriser</button></div></div></section>
    <section id="system" class="section"><div class="topbar"><div><div class="eyebrow">Diagnostics</div><h2>Système</h2><div class="muted">État de l’API, du modèle et des composants persistants.</div></div><button class="btn" onclick="loadHealth()">Tester</button></div><div class="card"><h3>Diagnostic</h3><div id="healthOutput" class="output">Chargement...</div></div></section>
  </main>
</div>
<div id="toast" class="toast"></div>
<script>
const $=id=>document.getElementById(id);const base='';
function toast(msg){const t=$('toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2400)}
function showPage(id){document.querySelectorAll('.section').forEach(x=>x.classList.remove('active'));document.querySelectorAll('.nav').forEach(x=>x.classList.toggle('active',x.dataset.page===id));$(id).classList.add('active');if(id==='missions')loadMissions();if(id==='memory')loadMemories();if(id==='system')loadHealth()}
document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>showPage(b.dataset.page));
async function api(path,opt={}){opt.credentials='same-origin';const r=await fetch(base+path,opt);const text=await r.text();let data;try{data=JSON.parse(text)}catch{data={error:text}}if(!r.ok)throw new Error(data.error||('HTTP '+r.status));return data}
async function authenticate(){const key=window.prompt('Clé d’accès Louis OS');if(!key)return;try{await api('/session',{method:'POST',headers:{'X-Louis-Key':key}});toast('Session sécurisée ouverte');refreshAll()}catch(e){toast(e.message)}}
function jsonHeaders(){return {'Content-Type':'application/json'}}
async function loadHealth(){try{const h=await api('/health');$('statusDot').classList.add('ok');$('statusText').textContent='En ligne · v'+h.version;$('systemState').textContent='En ligne';$('storeType').textContent=h.mission_store||'local';$('capabilities').innerHTML=['LLM : '+(h.llm_configured?'actif':'inactif'),'Core : '+(h.core||'standard'),'Mémoire : '+(h.memory_store||'local'),'Session web : authentification explicite'].join('<br>');$('healthOutput').textContent=JSON.stringify(h,null,2)}catch(e){$('statusText').textContent='Hors ligne';$('systemState').textContent='Erreur';$('healthOutput').textContent=e.message}}
function escapeHtml(s){return String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function missionItem(m){const status=m.status||'unknown',title=m.objective||m.mission_type||m.type||'Mission',id=m.mission_id||'';return `<div class="mission" onclick="viewMission('${id}')"><div><div class="mission-title">${escapeHtml(title)}</div><div class="mission-meta">${escapeHtml(m.mission_type||m.type||'')} · ${escapeHtml(id.slice(0,12))}</div></div><span class="badge ${escapeHtml(status)}">${escapeHtml(status)}</span></div>`}
function renderTraces(traces=[]){return traces.length?traces.map(t=>`<div class="trace"><div class="trace-stage">${escapeHtml(t.stage||'stage')}</div><div class="trace-agent">${escapeHtml(t.agent||'Agent')}</div><div class="trace-output">${escapeHtml(t.output||'')}</div></div>`).join(''):'<div class="empty">Aucune trace agent disponible.</div>'}
async function loadMissions(){try{const d=await api('/missions?limit=30');const arr=d.missions||[];$('missionCount').textContent=arr.length;const ok=arr.filter(x=>x.status==='completed').length;$('successRate').textContent=arr.length?Math.round(ok/arr.length*100)+'%':'—';$('recentMissions').innerHTML=arr.slice(0,6).map(missionItem).join('')||'<div class="empty">Aucune mission</div>';$('missionHistory').innerHTML=arr.map(missionItem).join('')||'<div class="empty">Aucune mission</div>'}catch(e){$('missionHistory').innerHTML='<div class="empty">'+escapeHtml(e.message)+'</div>'}}
async function viewMission(id){if(!id)return;showPage('missions');try{const d=await api('/missions/'+id);$('missionOutput').textContent=d.result||JSON.stringify(d,null,2);$('traceOutput').innerHTML=renderTraces(d.traces||[])}catch(e){toast(e.message)}}
$('missionForm').onsubmit=async e=>{e.preventDefault();let context;try{context=JSON.parse($('missionContext').value||'{}')}catch{return toast('Contexte JSON invalide')}const payload={type:$('missionType').value,objective:$('missionObjective').value.trim(),context:{...context,domain:$('missionDomain').value.trim()}};$('missionOutput').textContent='Mission en cours...';$('traceOutput').innerHTML='';try{const d=await api('/missions',{method:'POST',headers:jsonHeaders(),body:JSON.stringify(payload)});$('missionOutput').textContent=d.result||JSON.stringify(d,null,2);$('traceOutput').innerHTML=renderTraces(d.traces||[]);toast('Mission terminée');loadMissions()}catch(e){$('missionOutput').textContent=e.message}}
async function loadMemories(){const q=encodeURIComponent($('memoryQuery').value||'');try{const d=await api('/memories?limit=30&query='+q);const arr=d.memories||[];$('memoryList').innerHTML=arr.length?arr.map(m=>`<div class="mission"><div><div class="mission-title">${escapeHtml(m.content||'')}</div><div class="mission-meta">${escapeHtml(m.domain||'')} · ${escapeHtml(m.memory_type||m.type||'')}</div></div><span class="badge">${Math.round((m.confidence||0)*100)}%</span></div>`).join(''):'<div class="empty">Aucun résultat</div>'}catch(e){$('memoryList').innerHTML='<div class="empty">'+escapeHtml(e.message)+'</div>'}}
async function createMemory(){const payload={type:$('memoryType').value,domain:$('memoryDomain').value,content:$('memoryContent').value,confidence:.85,tags:[],source:'dashboard'};try{await api('/memories',{method:'POST',headers:jsonHeaders(),body:JSON.stringify(payload)});$('memoryContent').value='';toast('Mémoire enregistrée');loadMemories()}catch(e){toast(e.message)}}
async function refreshAll(){await loadHealth();await loadMissions()}
refreshAll();
</script>
</body></html>'''
